/**
 * Local stand-in for @deepseek-ai/dsh-atomic-write (DSH-internal utility).
 * Same semantics as the real one for this single-process bridge: write to a
 * temp file in the same directory, then rename over the target.
 */
import { mkdir, rename, writeFile } from "node:fs/promises";
import { basename, dirname, join } from "node:path";

/** The DSH lock is cross-process; a standalone bridge is single-process, so the call contract passes through. */
export async function withFileLock(_target, callback) {
  return await callback();
}

/** Atomic-enough write: temp file next to the target, then rename. */
export async function writeFileAtomic(path, data, options = undefined) {
  const dir = dirname(path);
  await mkdir(dir, { recursive: true });
  const tmp = join(dir, `.${basename(path)}.${process.pid}.${Date.now()}.tmp`);
  await writeFile(tmp, data, options);
  await rename(tmp, path);
}
